Muy bien. División por cero en C produce comportamiento indefinido. Siempre hay que protegerlo. Aquí está el programa completo:

```c
#include <stdio.h>

int main(void) {
    int N;
    printf("Cuántos elementos: ");
    scanf("%d", &N);

    int arr[N]; /* índices válidos: 0 .. N-1 */

    /* Loop 1: llenar el arreglo */
    for (int i = 0; i < N; i++) {
        printf("arr[%d]: ", i);
        scanf("%d", &arr[i]);
    }

    /* Loop 2: calcular promedio general */
    int suma = 0;
    for (int i = 0; i < N; i++) {
        suma += arr[i];
    }
    float promedio_general = (float)suma / N;
    printf("Promedio general: %.2f\n", promedio_general);

    /* Loop 3: promedio de los mayores al promedio general */
    float suma_mayores = 0.0f;
    int   count_mayores = 0;
    for (int i = 0; i < N; i++) {
        if (arr[i] > promedio_general) {
            suma_mayores += arr[i];
            count_mayores++;
        }
    }

    if (count_mayores > 0) {
        printf("Promedio de los mayores: %.2f\n",
               suma_mayores / count_mayores);
    } else {
        printf("Ningún elemento supera el promedio general.\n");
    }

    return 0;
}
```

Dos recorridos son la clave. Intentar hacerlo en uno solo es el error clásico en este ejercicio.
